/* Wine Folly service worker — generated by build_site.py.
 *
 * Served from the SITE ROOT (not assets/) so its scope covers every page.
 * VERSION changes on every build, which is what evicts the old cache: a
 * stale cache would keep showing wines you've since edited.
 *
 * Strategy: precache the shell and search index so a cold, offline launch
 * works; cache-first for everything else, filling as you browse. Once
 * you've opened a page it's yours in a cellar with no signal.
 */
const VERSION = "94a24105656b";
const CACHE = "WineFolly-" + VERSION;
const SHELL = ["./", "./index.html", "./wines.html", "./foods.html", "./regions.html", "./flavours.html", "./assets/style.css", "./assets/app.js", "./assets/icons/icon-192.png", "./data/index.json"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(SHELL))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))
      ))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  if (new URL(request.url).origin !== location.origin) return;

  event.respondWith(
    caches.match(request).then((hit) => {
      if (hit) {
        // refresh in the background so the next visit is current
        fetch(request).then((res) => {
          if (res && res.ok) caches.open(CACHE).then((c) => c.put(request, res));
        }).catch(() => {});
        return hit;
      }
      return fetch(request)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(request, copy));
          }
          return res;
        })
        .catch(() => caches.match(new URL("index.html", self.registration.scope).pathname));
    })
  );
});
